WITH filtered AS (SELECT id, product_name, brand, price, cost, stock_qty, launch_date, tags, supplier_id, INITCAP(TRIM(brand)) AS brand_title FROM products WHERE brand IS NOT NULL AND category = 'Sports') SELECT * FROM (SELECT supplier_id, brand, cost FROM filtered) src PIVOT (MAX(cost) AS value_sum, COUNT(1) AS cnt FOR brand IN ('Globex' AS globex, 'Umbrella' AS umbrella, 'Initech' AS initech));
